#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Detections;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Detections;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [BuffDefinition(VanillaBuffNames.Projectile.bentSpoon)]
    public class BentSpoonBuff : BuffDefinition
    {
        public BentSpoonBuff(string nsp, string name) : base(nsp, name)
        {
            absorbDetector = new SphereDetector(ABSORB_RADIUS);
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostProjectileHitCallback);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;

            detectBuffer.Clear();
            var target = absorbDetector.DetectEntityWithTheLeast(entity, e => Mathf.Abs(e.Position.magnitude - entity.Position.magnitude));
            if (target != null)
            {
                var vel = entity.Velocity;
                var speed = Mathf.Min(vel.magnitude + ABSORB_SPEED, ABSORB_MAX_SPEED);
                vel += (target.GetCenter() - entity.GetCenter()).normalized * ABSORB_SPEED;
                vel = vel.normalized * speed;
                entity.Velocity = vel;
            }
        }
        private void PostProjectileHitCallback(VanillaLevelCallbacks.PostProjectileHitParams param, CallbackResult result)
        {
            var hit = param.hit;
            var projectile = hit.Projectile;
            var buff = projectile.GetFirstBuff<BentSpoonBuff>();
            buff?.Remove();
        }
        public const float ABSORB_RADIUS = 80;
        public const float ABSORB_SPEED = 4;
        public const float ABSORB_MAX_SPEED = 10;
        private List<Entity> detectBuffer = new List<Entity>();
        private Detector absorbDetector;
    }
}
